import { useState } from 'react'
import { useForm } from '@tanstack/react-form'
import { zodValidator } from '@tanstack/zod-form-adapter'
import { z } from 'zod'
import './RegistrationForm.css'

// Zod schemas for each step
const firstNameSchema = z
  .string()
  .min(2, 'First name must be at least 2 characters')

const lastNameSchema = z
  .string()
  .min(2, 'Last name must be at least 2 characters')

const emailSchema = z.string().email('Please enter a valid email address')

const passwordSchema = z
  .string()
  .min(6, 'Password must be at least 6 characters')

// Full registration schema (used for final submission validation)
const registrationSchema = z.object({
  firstName: firstNameSchema,
  lastName: lastNameSchema,
  email: emailSchema,
  password: passwordSchema,
})

type RegistrationData = z.infer<typeof registrationSchema>

function RegistrationForm() {
  const [step, setStep] = useState<1 | 2>(1)
  const [submittedData, setSubmittedData] =
    useState<RegistrationData | null>(null)

  const form = useForm({
    defaultValues: {
      firstName: '',
      lastName: '',
      email: '',
      password: '',
    } as RegistrationData,
    // Form-level onChange validation triggers as the user types
    validators: {
      onChange: zodValidator(registrationSchema),
    },
    onSubmit: async ({ value }) => {
      // Stash the submitted data so we can render the success message
      setSubmittedData(value)
    },
  })

  const goToNextStep = async () => {
    // Trigger onChange validation, then inspect only the step 1 fields
    const fieldErrors = await form.validateAllFields('change')
    const step1FieldErrors = fieldErrors.filter((err) => {
      const fieldName =
        typeof err === 'object' && err !== null && 'fields' in err
          ? (err as { fields?: string[] }).fields
          : undefined
      return (
        fieldName?.includes('firstName') ||
        fieldName?.includes('lastName')
      )
    })

    if (step1FieldErrors.length === 0) {
      setStep(2)
    }
  }

  const goToPreviousStep = () => {
    setStep(1)
  }

  if (submittedData) {
    return (
      <div className="registration-success">
        <div id="success-message" data-testid="success-message">
          <h2>Registration successful! 🎉</h2>
          <p>Here is the data that was submitted:</p>
          <pre>{JSON.stringify(submittedData, null, 2)}</pre>
        </div>
      </div>
    )
  }

  return (
    <div className="registration-container">
      <header className="registration-header">
        <h1>Create your account</h1>
        <p className="step-indicator">
          Step {step} of 2 — {step === 1 ? 'User info' : 'Account info'}
        </p>
      </header>

      <form
        onSubmit={(e) => {
          e.preventDefault()
          e.stopPropagation()
          if (step === 1) {
            void goToNextStep()
          } else {
            void form.handleSubmit()
          }
        }}
      >
        {step === 1 && (
          <fieldset className="form-step">
            <legend>User information</legend>

